package com.inmobiliaria.controlador; import com.inmobiliaria.dao.CitaDAO; import com.inmobiliaria.modelo.Cita; import com.inmobiliaria.modelo.Usuario; import javax.servlet.ServletException; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.IOException; import java.sql.Timestamp; import java.time.LocalDateTime; import java.time.format.DateTimeParseException; import java.util.List; import java.util.logging.Level; import java.util.logging.Logger; @WebServlet("/citas") public class CitaServlet extends HttpServlet { private static final Logger LOGGER = Logger.getLogger(CitaServlet.class.getName()); private static final String ESTADO_PENDIENTE = "Pendiente"; private static final String ESTADO_CONFIRMADA = "Confirmada"; private static final String ESTADO_CANCELADA = "Cancelada"; private CitaDAO citaDAO; @Override public void init() throws ServletException { super.init(); this.citaDAO = new CitaDAO(); } @Override protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException { Usuario usuario = obtenerUsuarioAutenticado(request, response); if (usuario == null) return; String accion = leerParametro(request, "accion", "listar"); try { switch (accion) { case "listar": listarCitas(request, response, usuario); break; case "cancelar": case "confirmar": response.sendError(HttpServletResponse.SC_METHOD_NOT_ALLOWED, "La operación debe hacerse por POST."); break; default: listarCitas(request, response, usuario); break; } } catch (Exception e) { manejarError(request, response, "Error al procesar la cita.", e); } } @Override protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException { request.setCharacterEncoding("UTF-8"); Usuario usuario = obtenerUsuarioAutenticado(request, response); if (usuario == null) return; String accion = leerParametro(request, "accion", ""); try { switch (accion) { case "agendar": agendarCita(request, response, usuario); break; case "cancelar": cambiarEstadoCita(request, response, usuario, ESTADO_CANCELADA); break; case "confirmar": cambiarEstadoCita(request, response, usuario, ESTADO_CONFIRMADA); break; default: response.sendRedirect(request.getContextPath() + "/citas?accion=listar"); break; } } catch (IllegalArgumentException e) { LOGGER.log(Level.WARNING, "Parámetros inválidos al procesar cita", e); request.setAttribute("error", e.getMessage()); request.getRequestDispatcher("/error.jsp").forward(request, response); } catch (Exception e) { manejarError(request, response, "Error al procesar la operación de la cita.", e); } } private Usuario obtenerUsuarioAutenticado(HttpServletRequest request, HttpServletResponse response) throws IOException { HttpSession session = request.getSession(false); if (session == null || session.getAttribute("usuario") == null) { response.sendRedirect(request.getContextPath() + "/login.jsp"); return null; } Object obj = session.getAttribute("usuario"); if (!(obj instanceof Usuario)) { session.invalidate(); response.sendRedirect(request.getContextPath() + "/login.jsp"); return null; } return (Usuario) obj; } private boolean esCliente(Usuario usuario) { if (usuario == null) return false; String rol = usuario.getRol(); return rol != null && ("Cliente".equalsIgnoreCase(rol) || "CLIENTE".equalsIgnoreCase(rol)); } private boolean esAdminOInmobiliaria(Usuario usuario) { if (usuario == null) return false; String rol = usuario.getRol(); return rol != null && ( "Admin".equalsIgnoreCase(rol) || "ADMIN".equalsIgnoreCase(rol) || "Inmobiliaria".equalsIgnoreCase(rol) || "GESTOR".equalsIgnoreCase(rol) || "Gestor".equalsIgnoreCase(rol) ); } private void listarCitas(HttpServletRequest request, HttpServletResponse response, Usuario usuario) throws Exception { List<Cita> listaCitas; if (esCliente(usuario)) { listaCitas = citaDAO.listarPorCliente(usuario.getIdUsuario()); } else if (esAdminOInmobiliaria(usuario)) { listaCitas = citaDAO.listarTodas(); } else { response.sendError(HttpServletResponse.SC_FORBIDDEN, "No tiene permisos para consultar citas."); return; } request.setAttribute("citas", listaCitas); request.getRequestDispatcher("/citas/lista.jsp").forward(request, response); } private void agendarCita(HttpServletRequest request, HttpServletResponse response, Usuario cliente) throws Exception { if (!esCliente(cliente)) { response.sendError(HttpServletResponse.SC_FORBIDDEN, "Solo los clientes pueden agendar citas."); return; } int idPropiedad = leerEnteroPositivo(request, "idPropiedad"); LocalDateTime fechaHoraLocal = leerFechaHora(request, "fechaHora"); if (!fechaHoraLocal.isAfter(LocalDateTime.now())) { throw new IllegalArgumentException("La fecha y hora de la cita deben ser futuras."); } Cita nuevaCita = new Cita(); nuevaCita.setIdPropiedad(idPropiedad); nuevaCita.setIdCliente(cliente.getIdUsuario()); nuevaCita.setFechaHora(Timestamp.valueOf(fechaHoraLocal)); nuevaCita.setEstado(ESTADO_PENDIENTE); boolean creada = citaDAO.crear(nuevaCita); if (creada) { request.getSession().setAttribute("mensajeExito", "Cita agendada correctamente."); response.sendRedirect(request.getContextPath() + "/citas?accion=listar"); } else { request.getSession().setAttribute("mensajeError", "El horario seleccionado ya no está disponible para este inmueble."); response.sendRedirect(request.getContextPath() + "/propiedades?accion=ver&id=" + idPropiedad); } } private void cambiarEstadoCita(HttpServletRequest request, HttpServletResponse response, Usuario usuario, String nuevoEstado) throws Exception { int idCita = leerEnteroPositivo(request, "id"); Cita cita = citaDAO.obtenerPorId(idCita); if (cita == null) { response.sendError(HttpServletResponse.SC_NOT_FOUND, "La cita no existe."); return; } if (!puedeModificarCita(usuario, cita, nuevoEstado)) { response.sendError(HttpServletResponse.SC_FORBIDDEN, "No tiene permisos para modificar esta cita."); return; } if (!estadoPermitido(cita.getEstado(), nuevoEstado)) { request.getSession().setAttribute("mensajeError", "La cita no puede pasar de " + cita.getEstado() + " a " + nuevoEstado + "."); response.sendRedirect(request.getContextPath() + "/citas?accion=listar"); return; } boolean actualizado = citaDAO.actualizarEstado(idCita, nuevoEstado); if (actualizado) { request.getSession().setAttribute("mensajeExito", "La cita ha sido marcada como " + nuevoEstado + "."); } else { request.getSession().setAttribute("mensajeError", "No se pudo actualizar la cita."); } response.sendRedirect(request.getContextPath() + "/citas?accion=listar"); } private boolean puedeModificarCita(Usuario usuario, Cita cita, String nuevoEstado) { if (esAdminOInmobiliaria(usuario)) { return true; } if (esCliente(usuario)) { return ESTADO_CANCELADA.equals(nuevoEstado) && cita.getIdCliente() == usuario.getIdUsuario(); } return false; } private boolean estadoPermitido(String estadoActual, String nuevoEstado) { if (estadoActual == null || nuevoEstado == null) return false; if (ESTADO_CANCELADA.equals(estadoActual)) return false; if (ESTADO_CONFIRMADA.equals(nuevoEstado)) { return ESTADO_PENDIENTE.equals(estadoActual); } if (ESTADO_CANCELADA.equals(nuevoEstado)) { return ESTADO_PENDIENTE.equals(estadoActual) || ESTADO_CONFIRMADA.equals(estadoActual); } return false; } private String leerParametro(HttpServletRequest request, String nombre, String defecto) { String valor = request.getParameter(nombre); if (valor == null) return defecto; valor = valor.trim(); return valor.isEmpty() ? defecto : valor; } private int leerEnteroPositivo(HttpServletRequest request, String nombre) { String valor = leerParametro(request, nombre, ""); if (valor.isEmpty()) { throw new IllegalArgumentException("El parámetro '" + nombre + "' es obligatorio."); } try { int numero = Integer.parseInt(valor); if (numero <= 0) { throw new IllegalArgumentException("El parámetro '" + nombre + "' debe ser mayor que cero."); } return numero; } catch (NumberFormatException e) { throw new IllegalArgumentException("El parámetro '" + nombre + "' debe ser un número válido."); } } private LocalDateTime leerFechaHora(HttpServletRequest request, String nombre) { String valor = leerParametro(request, nombre, ""); if (valor.isEmpty()) { throw new IllegalArgumentException("La fecha y hora de la cita son obligatorias."); } try { return LocalDateTime.parse(valor); } catch (DateTimeParseException e) { throw new IllegalArgumentException("La fecha y hora de la cita no tienen un formato válido."); } } private void manejarError(HttpServletRequest request, HttpServletResponse response, String mensaje, Exception e) throws ServletException, IOException { LOGGER.log(Level.SEVERE, mensaje, e); request.setAttribute("error", mensaje); request.getRequestDispatcher("/error.jsp").forward(request, response); } }
